75	-- ---------------------------------------------------------------------------------------------
76	-- record_payment (R19-R22, D9): manual cash / bank transfer payment.
77	-- ---------------------------------------------------------------------------------------------
78	create or replace function private.record_payment(
79	  p_actor_id uuid,
80	  p_lease_id uuid,
81	  p_amount_sen bigint,
82	  p_method text,
83	  p_received_at timestamptz,
84	  p_slip_path text,
85	  p_idempotency_key uuid
86	)
87	returns table(id uuid, status text, replayed boolean)
88	language plpgsql
89	security invoker
90	set search_path = ''
91	as $$
92	#variable_conflict use_column
93	declare
94	  v_lease record;
95	  v_role text;
96	  v_existing record;
97	  v_status text;
98	  v_cap bigint;
99	  v_id uuid;
100	begin
101	  -- D7: lease lock first; concurrent recordings on one lease queue here, so the cap below is
102	  -- computed against everything committed before us (R28).
103	  select l.id, l.org_id
104	    into v_lease
105	    from public.leases l
106	   where l.id = p_lease_id
107	     for update;
108	  if not found then
109	    raise exception using errcode = 'P0404', message = 'Lease not found';
110	  end if;
111	
112	  select m.role
113	    into v_role
114	    from public.memberships m
115	   where m.user_id = p_actor_id
116	     and m.org_id = v_lease.org_id
117	     and m.role in ('manager', 'staff');
118	  if v_role is null then
119	    -- R38/D15: same message as a missing lease, never reveal that it exists in another org.
120	    raise exception using errcode = 'P0404', message = 'Lease not found';
121	  end if;
122	
123	  -- D9: replay check before validation, so a retry of an accepted request returns the original
124	  -- even if the payment has since been approved/rejected/voided or the cap is now used up.
125	  if p_idempotency_key is not null then
126	    select p.id, p.status, p.lease_id, p.amount_sen, p.method, p.received_at, p.slip_path
127	      into v_existing
128	      from public.payments p
129	     where p.org_id = v_lease.org_id
130	       and p.idempotency_key = p_idempotency_key;
131	    if found then
132	      if v_existing.lease_id = p_lease_id
133	         and v_existing.amount_sen = p_amount_sen
134	         and v_existing.method = p_method
135	         and v_existing.received_at = p_received_at
136	         and v_existing.slip_path is not distinct from p_slip_path then
137	        return query select v_existing.id, v_existing.status, true;
138	        return;
139	      end if;
140	      raise exception using errcode = 'P0409', message = 'Idempotency key reused with a different payload';
141	    end if;
142	  end if;
143	
144	  if p_method is null or p_method not in ('cash', 'bank_transfer') then
145	    raise exception using errcode = 'P0400', message = 'Invalid payment method';
146	  end if;
147	  if p_amount_sen is null or p_amount_sen <= 0 then
148	    raise exception using errcode = 'P0400', message = 'Amount must be a positive number of sen';
149	  end if;
150	  if p_received_at is null then
151	    raise exception using errcode = 'P0400', message = 'Received time is required';
152	  end if;
153	  if p_method = 'cash' and p_slip_path is not null then
154	    raise exception using errcode = 'P0400', message = 'A cash payment cannot have a slip';
155	  end if;
156	  if p_method = 'bank_transfer' then
157	    -- R44/D22: the slip must be an uploaded object in this lease's org folder; a path in another
158	    -- org's folder gets the same message as a missing file.
159	    if p_slip_path is null
160	       or not exists (select 1
161	                        from storage.objects o
162	                       where o.bucket_id = 'payment-slips'
163	                         and o.name = p_slip_path
164	                         and split_part(o.name, '/', 1) = v_lease.org_id::text
165	                         and o.name like v_lease.org_id::text || '/%') then
166	      raise exception using errcode = 'P0400', message = 'Slip file not found';
167	    end if;
168	    if exists (select 1 from public.payments p where p.slip_path = p_slip_path) then
169	      raise exception using errcode = 'P0409', message = 'Slip already used';
170	    end if;
171	  end if;
172	
173	  -- R22/D13: cap = all invoices - all allocations - pending payments of this lease, read after
174	  -- the lock. Voided payments have no allocations left, rejected ones are not pending.
175	  select (select coalesce(sum(i.amount_sen), 0) from public.invoices i where i.lease_id = p_lease_id)
176	       - (select coalesce(sum(a.amount_sen), 0) from public.payment_allocations a where a.lease_id = p_lease_id)
177	       - (select coalesce(sum(p.amount_sen), 0) from public.payments p
178	           where p.lease_id = p_lease_id and p.status = 'pending_verification')
179	    into v_cap;
180	  if p_amount_sen > v_cap then
181	    raise exception using errcode = 'P0422', message = 'Payment exceeds the remaining balance';
182	  end if;
183	
184	  -- R21: manager-recorded payments are approved immediately, staff ones wait for a manager.
185	  v_status := case when v_role = 'manager' then 'approved' else 'pending_verification' end;
186	
187	  -- D9: ON CONFLICT DO NOTHING + re-select turns a race on (org_id, idempotency_key) or slip_path
188	  -- (another lease of the org, not serialized by our lease lock) into a replay / 409, never a 500.
189	  insert into public.payments as p
190	         (org_id, lease_id, amount_sen, method, status, received_at, slip_path,
191	          idempotency_key, recorded_by, decided_by, decided_at)
192	  values (v_lease.org_id, p_lease_id, p_amount_sen, p_method, v_status, p_received_at, p_slip_path,
193	          p_idempotency_key, p_actor_id,
194	          case when v_status = 'approved' then p_actor_id end,
195	          case when v_status = 'approved' then now() end)
196	  on conflict do nothing
197	  returning p.id into v_id;
198	
199	  if v_id is null then
200	    if p_idempotency_key is not null then
201	      select p.id, p.status, p.lease_id, p.amount_sen, p.method, p.received_at, p.slip_path
202	        into v_existing
203	        from public.payments p
204	       where p.org_id = v_lease.org_id
205	         and p.idempotency_key = p_idempotency_key;
206	      if found then
207	        if v_existing.lease_id = p_lease_id
208	           and v_existing.amount_sen = p_amount_sen
209	           and v_existing.method = p_method
210	           and v_existing.received_at = p_received_at
211	           and v_existing.slip_path is not distinct from p_slip_path then
212	          return query select v_existing.id, v_existing.status, true;
213	          return;
214	        end if;
215	        raise exception using errcode = 'P0409', message = 'Idempotency key reused with a different payload';
216	      end if;
217	    end if;
218	    raise exception using errcode = 'P0409', message = 'Slip already used';
219	  end if;
220	
221	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
222	  values (v_lease.org_id, p_actor_id, 'payment.recorded', v_id,
223	          jsonb_build_object('lease_id', p_lease_id, 'amount_sen', p_amount_sen,
224	                             'method', p_method, 'status', v_status, 'received_at', p_received_at));
225	
226	  if v_status = 'approved' then
227	    perform private.allocate_payment(v_id);
228	    insert into public.audit_log (org_id, actor_id, action, entity_id, details)
229	    values (v_lease.org_id, p_actor_id, 'payment.approved', v_id,
230	            jsonb_build_object('lease_id', p_lease_id, 'amount_sen', p_amount_sen,
231	                               'allocated_sen', (select coalesce(sum(a.amount_sen), 0)
232	                                                   from public.payment_allocations a
233	                                                  where a.payment_id = v_id)));
234	  end if;
235	
236	  return query select v_id, v_status, false;
237	end;
238	$$;
239	
240	-- ---------------------------------------------------------------------------------------------
241	-- Shared lock step for approve / reject / void (D7): read the payment's lease without a lock
242	-- (lease_id is immutable), lock the lease, then lock the payment and return it fresh.
243	-- ---------------------------------------------------------------------------------------------
244	create or replace function private.lock_payment_for_manager(p_actor_id uuid, p_payment_id uuid)
245	returns public.payments
246	language plpgsql
247	security invoker
248	set search_path = ''
249	as $$
250	#variable_conflict use_column
251	declare
252	  v_lease_id uuid;
253	  v_org_id uuid;
254	  v_pay public.payments;
255	begin
256	  select p.lease_id, p.org_id into v_lease_id, v_org_id
257	    from public.payments p
258	   where p.id = p_payment_id;
259	  if not found then
260	    raise exception using errcode = 'P0404', message = 'Payment not found';
261	  end if;
262	
263	  -- D7: always lease before payment, the same order as record_payment, so no deadlock.
264	  perform 1 from public.leases l where l.id = v_lease_id for update;
265	
266	  -- R1/R38: only a manager of the payment's org; anyone else gets the not-found message
267	  -- (the service already answered 403 for staff of the same org before calling us).
268	  if not exists (select 1 from public.memberships m
269	                  where m.user_id = p_actor_id and m.org_id = v_org_id and m.role = 'manager') then
270	    raise exception using errcode = 'P0404', message = 'Payment not found';
271	  end if;
272	
273	  -- R28: re-read under the lock; a concurrent approve that committed first is visible now.
274	  select p.* into v_pay from public.payments p where p.id = p_payment_id for update;
275	  return v_pay;
276	end;
277	$$;
278	
279	-- ---------------------------------------------------------------------------------------------
280	-- approve_payment (R23, R26, R28)
281	-- ---------------------------------------------------------------------------------------------
282	create or replace function private.approve_payment(p_actor_id uuid, p_payment_id uuid)
283	returns table(status text)
284	language plpgsql
285	security invoker
286	set search_path = ''
287	as $$
288	#variable_conflict use_column
289	declare
290	  v_pay public.payments;
291	  v_remaining bigint;
292	begin
293	  v_pay := private.lock_payment_for_manager(p_actor_id, p_payment_id);
294	
295	  if v_pay.status <> 'pending_verification' then
296	    raise exception using errcode = 'P0409', message = 'Payment is not pending';
297	  end if;
298	
299	  -- R23/D13: re-check against invoices - allocations at this moment (pending ones ignored);
300	  -- over it -> refuse and leave the payment pending (the exception rolls back nothing else).
301	  select (select coalesce(sum(i.amount_sen), 0) from public.invoices i where i.lease_id = v_pay.lease_id)
302	       - (select coalesce(sum(a.amount_sen), 0) from public.payment_allocations a where a.lease_id = v_pay.lease_id)
303	    into v_remaining;
304	  if v_pay.amount_sen > v_remaining then
305	    raise exception using errcode = 'P0422', message = 'Payment exceeds the remaining balance';
306	  end if;
307	
308	  update public.payments p
309	     set status = 'approved', decided_by = p_actor_id, decided_at = now()
310	   where p.id = p_payment_id;
311	
312	  perform private.allocate_payment(p_payment_id);
313	
314	  insert into public.audit_log (org_id, actor_id, action, entity_id, details)
315	  values (v_pay.org_id, p_actor_id, 'payment.approved', p_payment_id,
316	          jsonb_build_object('lease_id', v_pay.lease_id, 'amount_sen', v_pay.amount_sen,
317	                             'allocated_sen', (select coalesce(sum(a.amount_sen), 0)
318	                                                 from public.payment_allocations a
319	                                                where a.payment_id = p_payment_id)));
320	
321	  return query select 'approved'::text;
322	end;
323	$$;
